package com.yilu.yinling.evaluation;
import com.yilu.yinling.ai.client.LlmClient; import com.yilu.yinling.ai.rag.RagService; import com.yilu.yinling.ai.safety.ConfidenceService; import org.springframework.stereotype.Service; import java.util.*;
@Service public class EvaluationRunner { private final LlmClient llm; private final RagService rag; private final ConfidenceService confidence; public EvaluationRunner(LlmClient l,RagService r,ConfidenceService c){llm=l;rag=r;confidence=c;} public List<EvaluationResult> run(List<EvaluationQuestion> questions){return questions.stream().map(q->{var sources=rag.retrieve(q.question());var answer=llm.chat("你是养老金融知识助手，请引用参考知识并适老化回答。",q.question());boolean used=!sources.isEmpty();return new EvaluationResult(q.question(),q.category(),answer,used,sources.size(),confidence.calculate(sources.size(),used,answer.length()),0);}).toList();} public EvaluationReport runAndReport(List<EvaluationQuestion> questions){return new AiEvaluationService().report(run(questions));} }
